const item = $input.first().json;
const competitor = item.competitor_name || 'Competitor';
const previous = item.previous_snapshot || '';
const current = item.current_snapshot || '';

const analysisPrompt = `Analyze the pricing and product changelog shift for competitor "${competitor}":

--- PREVIOUS PRICING & FEATURES SNAPSHOT ---
${previous}

--- CURRENT PRICING & FEATURES SNAPSHOT ---
${current}`;

return [{
  json: {
    competitor_name: competitor,
    competitor_url: item.competitor_url || 'https://competitor.com',
    analysis_prompt: analysisPrompt
  }
}];

const data = $('Market Intelligence AI Agent').item.json.output || $('Market Intelligence AI Agent').item.json;
const competitor = $('Prepare Data for Analysis').item.json;

const pricingChanges = Array.isArray(data.key_pricing_changes) ? data.key_pricing_changes : [data.key_pricing_changes || 'Price adjustments detected'];
const features = Array.isArray(data.new_features_detected) ? data.new_features_detected : [data.new_features_detected || 'Feature updates detected'];
const actions = Array.isArray(data.recommended_counter_actions) ? data.recommended_counter_actions : [data.recommended_counter_actions || 'Monitor competitor analytics'];

const urgentAlert = `
🚨 **CRITICAL COMPETITIVE THREAT DETECTED (Threat Score: ${data.threat_score}/100)** 🚨

🏢 **Competitor:** ${competitor.competitor_name} (${competitor.competitor_url})

📝 **Executive Summary:**
${data.executive_summary}

💰 **Pricing & Quota Changes:**
${pricingChanges.map(p => '• ' + p).join('\n')}

🚀 **New Features / Capabilities:**
${features.map(f => '• ' + f).join('\n')}

🎯 **Strategic Counter-Actions Recommended:**
${actions.map((a, i) => `${i+1}. ${a}`).join('\n')}

📌 **Action Required:** Immediate product & marketing sync recommended.
`;

return [{
  json: {
    alert_type: 'CRITICAL_THREAT',
    notification_markdown: urgentAlert,
    competitor: competitor.competitor_name,
    threat_score: data.threat_score
  }
}];

const data = $('Market Intelligence AI Agent').item.json.output || $('Market Intelligence AI Agent').item.json;
const competitor = $('Prepare Data for Analysis').item.json;

const digest = `
📊 **COMPETITIVE DIGEST: ${competitor.competitor_name} (Score: ${data.threat_score}/100)** 📊

📝 **Summary:** ${data.executive_summary}
📌 **Status:** Logged for monthly product roadmap review.
`;

return [{
  json: {
    alert_type: 'MODERATE_DIGEST',
    notification_markdown: digest,
    competitor: competitor.competitor_name,
    threat_score: data.threat_score
  }
}];

const data = $('Market Intelligence AI Agent').item.json.output || $('Market Intelligence AI Agent').item.json;
const competitor = $('Prepare Data for Analysis').item.json;

return [{
  json: {
    intel_record_id: 'INTEL-' + Date.now(),
    competitor_name: competitor.competitor_name,
    threat_score: data.threat_score,
    impact_level: data.impact_level,
    executive_summary: data.executive_summary,
    pricing_changes: data.key_pricing_changes,
    new_features: data.new_features_detected,
    recommended_actions: data.recommended_counter_actions,
    recorded_at: new Date().toISOString(),
    status: 'INTELLIGENCE_DISPATCHED'
  }
}];
